from typing import List
from functools import cmp_to_key

def sort_numbers(numbers: str) -> str:
    def custom_compare(a, b):
        return (number_dict[a] > number_dict[b]) - (number_dict[a] < number_dict[b])

    number_dict = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    # Convert the string of numbers to a list of integers for sorting
    number_list = [number_dict[num] for num in numbers.split()]

    # Sort the list using the custom comparison function
    sorted_list = sorted(number_list, key=cmp_to_key(custom_compare))

    # Convert the sorted list of integers back to a space-delimited string
    return ' '.join([str(num) for num in sorted_list])

