from typing import List
from typing import List
import numpy as np

def rescale_to_unit(numbers: List[float]) -> List[float]:
    min_val = min(numbers)
    max_val = max(numbers)
    range_val = max_val - min_val
    if range_val == 0:
        return [0.0] * len(numbers)
    scaled = np.array([(x - min_val) / range_val for x in numbers])
    return scaled.tolist()

